B="BK-741"
C=[
("S16",4652,4671,"مضاهاة الأختام: الإطار والأبعاد والنقوش والمسافات وسُمك الخط","يعدد الكتاب عناصر مقارنة بصمة ختم بنماذج معروفة: شكل الإطار وأبعاده، النقوش وأوضاعها، المسافات بين الأجزاء، وسمك الخطوط. تنتهي المقارنة إلى ثلاث نتائج: أخذت من القالب نفسه، أو من قالب مختلف، أو مصنوعة بالرسم أو النقل.","اطلب مقارنة منظمة بعناصر محددة لا حكماً بالنظرة.","ختم من نفس القالب قد يبدو مختلفاً بسبب الحبر والضغط وطريقة الطبع.","","16-18","safe","lab_limits",["KO-FC-04-016","KO-FC-04B-005"],["ختم","عناصر مقارنة"]),
("S16",4651,4651,"قالب الختم جسم منفصل عن صاحبه فقد يملكه غيره أو يُنسخ","ينبه الكتاب إلى أن القالب شيء مادي ينتقل بين الأيدي أو يُقلَّد، وأن بصمة الختم الصحيحة تدل على القالب لا على اليد التي ضغطت به. تمييز هذه النقطة يمنع نسبة التصرف لصاحب الختم تلقائياً.","عند وجود ختم: اسأل من كان يحتفظ بالقالب ومن لديه وصول إليه؟","ثبوت أصالة القالب لا يثبت هوية الضاغط.","الختم الصحيح يعني أن صاحبه وقّع.","16-18","conceptual","witness_reliability",["KO-RS-06-004","KO-RS-05-004"],["قالب","حيازة"]),
("S17",4705,4716,"تقدير عمر الوثيقة يبدأ بالفحص غير المتلف للورقة","يذكر الكتاب فحص سطح الورقة وحوافها ومواضع طيّها وتماسكها وعلاماتها المائية قبل أي فحص كيميائي. تتغير الورقة مع الزمن بطرق مرئية: لون، هشاشة حواف، تآكل مواضع الطي. محاولات إظهار القدم صناعياً قد تترك أثرا مغايراً.","في اللعبة: سلسلة أدلة بصرية على عمر ورقة: حواف، لون، طيّات، ثم مقارنة بورقة مرجعية.","الحفظ الجيد في خزانة قد يُبطئ علامات القدم فيظهر المستند أحدث مما هو.","","13-15","safe","timing",["KO-FC-04-021","KO-FC-04-019","KO-FC-04-026"],["قِدم الورق","فحص غير متلف"]),
("S17",4746,4751,"قبل أي معمل: اختبر منطق التواريخ ضد وقائع التاريخ والتقنية","يوضح الكتاب أن الخبير يفحص أولاً توافق تواريخ المستند مع ظهور أدوات الكتابة ونوع الورق وأحداث معروفة، فمستند مؤرخ بتاريخ يسبق اختراع قلم مستعمل فيه يكشف نفسه. من الأمثلة خطأ تقويم أو مفكرة طُبعت بعد التاريخ المدون.","استخدم مسطرة زمنية للتقنيات والأحداث وقارنها بتاريخ الوثيقة: هل في الوثيقة ما لم يكن موجوداً وقتها؟","غياب التناقض الزمني لا يثبت الأصالة.","","13-15","safe","timing",["KO-RS-05-005","KO-RS-06-017","KO-FC-04-019"],["مفارقة زمنية","مسطرة زمنية"]),
("S17",4752,4765,"تاريخ المحرر لا يحتج به على الغير إلا حين يثبت بدليل خارجي","يذكر الكتاب قاعدة قانونية تقول إن تاريخ المحرر العرفي لا يعد حجة على غير أطرافه إلا بتسجيل أو إشارة موظف مختص أو واقعة تؤكد وجوده قبلها. الدرس العام: التاريخ المكتوب على المستند ادعاء حتى يؤيده مصدر مستقل.","اسأل: ما الدليل المستقل على أن هذه الوثيقة وُجدت في هذا التاريخ؟","القاعدة خاصة بالنظام المصري.","التاريخ المكتوب على الورقة يثبت وقت كتابتها.","16-18","conceptual","timing",["KO-RS-05-001","KO-RS-05-005","KO-RS-05-014"],["تاريخ ثابت","مصدر مستقل"]),
("S17",4766,4772,"اختلاف أداة الكتابة داخل المتن قد يدل على إضافة لاحقة","يقرر الكتاب أن المستند الصحيح غالباً يُكتب متنه بأداة واحدة، فتباين الأدوات في المتن قد يكشف إضافة. أما التوقيعات فقد تختلف أدواتها لأن كل موقّع يستخدم أداته، ولا يدل ذلك وحده على اختلاف التواريخ.","فرّق بين متن المستند وتوقيعاته عند تحليل الأدوات.","اختلاف الأداة قد يعود لنفاد الحبر أو استعارة قلم.","","13-15","safe","lab_limits",["KO-FC-04-019","KO-RS-06-004"],["أداة كتابة","إضافة لاحقة"]),
("S17",4773,4786,"ألوان الأحبار تتغير بالزمن بحسب نوعها وظروفها","يعرض الكتاب أن بعض الأحبار الملونة تبهت سريعاً، وأن الأحبار الحديدية تتحول تدريجياً في لونها، وأن الأحبار الكربونية أكثر ثباتاً، وأن المقارنة تتم مع نموذج معلوم التاريخ ومن النوع نفسه. لا يمكن تقدير عمر بمجرد إدراك اللون.","اقرن كل تقدير زمني بمرجع من الحبر والورق نفسيهما وبظروف حفظ متقاربة.","اللون يتأثر بالضوء والرطوبة وجودة الورق فيعطي نطاقاً واسعاً.","","16-18","conceptual","timing",["KO-FC-04-021","KO-RS-07B-001","KO-FC-04-019"],["تغير اللون","مرجع زمني"]),
("S17",4797,4849,"تقدير عمر الحبر بانتشار الأيونات: طريقة حساسة وعوامل مؤثرة كثيرة","يقر الكتاب بأن هذا الاختبار يتأثر بالرطوبة والحرارة والضوء وأملاح الورق، ولذلك يقترح شروطاً مثل نماذج مماثلة معلومة التاريخ وجزء كتابة متقارب السمك وضوء خافت. أنجح استعمال له مقارنة عبارات على ورقة واحدة بعضها معلوم التاريخ. لا نذكر المقادير ولا الخطوات هنا.","احكم على أي تقدير زمني من خلال: هل الظروف مضبوطة؟ هل المرجع مماثل؟ هل ذُكر هامش خطأ؟","هذه طريقة قديمة وتتطلب تحققاً قبل الاستناد إليها اليوم.","المختبر يحدد التاريخ بدقة.","18+","conceptual","lab_limits",["KO-FC-04-021","KO-FC-04-019","KO-FC-04-031"],["هامش خطأ","ضبط الظروف"]),
("S17",4850,4912,"الكتابة غير المرئية تُطلب بوسائل غير متلفة أولاً","يذكر الكتاب أن مراسلات خفية قد تُكتب بسوائل لا تُرى بالعين، وأن الفحص يبدأ بالإضاءة المنعكسة والجانبية والأشعة فوق البنفسجية وتحت الحمراء ثم يتدرج إلى وسائل أكثر تدخلاً، مع تحذير من أن بعض الطرق تتلف المكتوب الظاهر. المبدأ: رتّب الفحوص من الأقل إلى الأكثر إتلافاً.","في اللعبة: رسالة تبدو فارغة، والمطلوب ترتيب الفحوص بحيث لا نُتلف الدليل.","ما يُكتشف قد لا يكون كاملاً، والاستعمال المتلف قد لا يمكن تكراره.","","13-15","safe","lab_limits",["KO-FC-04-019","KO-FC-04-026"],["كتابة خفية","ترتيب الفحوص"]),
("S17",4912,4936,"الأوراق المحترقة تحتاج حذراً قبل أي فحص","يقرر الكتاب أن أول عقبة هي نقل الورق المحروق دون كسره، وأن بعض الأحبار تترك أثراً يمكن إظهاره بالضوء المائل والتصوير بالأشعة تحت الحمراء. يبدأ الفحص بالأساليب غير المتلفة. المبدأ: الحفظ والتوثيق قبل التدخل.","قبل لمس أي بقايا محترقة: صوّرها في مكانها واحفظها في حامل صلب.","الأثر المتبقي قد لا يكفي لقراءة النص.","الحريق يمحو كل الوثائق.","13-15","safe","evidence_handling",["KO-FC-04-026","KO-RS-05-013"],["بقايا محترقة","تصوير أولاً"]),
("S18",4937,4946,"الأرقام التسلسلية المبرودة قد تترك أثراً في عمق المعدن","يذكر الكتاب أن العلامات المطروقة على المعدن تغير بنيته تحتها، فإذا بُردت من السطح ظل الأثر أعمق. وهذا سبب اهتمام المحققين بأرقام المركبات والأجهزة. نذكر المبدأ فحسب دون أي وسائل.","في الألغاز: رقم مبرود في جهاز مسروق دليل بحد ذاته، ومعمل مختص يمكن أن يستعيده.","استعادة الرقم تعتمد على المعدن وعمق المحو وقد لا تنجح.","","13-15","conceptual","lab_limits",["KO-FC-04-019","KO-FC-04-026"],["رقم تسلسلي","أثر عميق"]),
("S18",4947,5014,"إظهار العلامات المزالة عمل مختبري متخصص لا تجربة منزلية","يستعرض الكتاب أنواعاً من المعادن ومحاليل لإظهار العلامات، ويذكر طرقاً فيزيائية كالمغناطيس والتسخين الخفيف. هنا نكتفي بالقول إن الاختيار مرتبط بنوع المعدن وإن التصوير قبل أي معالجة ضروري، وإن التجريب غير المتخصص قد يتلف الأثر نهائياً.","اطلب دائماً إحالة الأجهزة المبرودة الأرقام إلى مختبر مختص بعد التصوير.","المعالجات الكيميائية خطرة وتتلف الدليل، ولا تُجرى خارج مختبر.","","18+","sensitive","evidence_handling",["KO-FC-04-026","KO-FC-04B-002"],["إحالة للمختبر","تصوير قبل المعالجة"]),
("S19",5024,5041,"أول من يصل إلى المسرح مسؤول عن حفظ الأدلة قبل أي شيء","يعدّد الكتاب واجبات أولية: حصر المكان، عدم تحريك أي شيء قبل وصفه، منع الدخول والخروج، فصل المشتبه بهم عن الشهود وبعضهم عن بعض، فحص المشتبه وملابسه، ومنع الهرب. القصد: منع ضياع الأدلة وتلاقح الروايات.","طبّق قائمة الستة في مشهد أول وصول، ثم اسأل: ما الذي لا يمكن استعادته لو أُهمل؟","الإجراءات المثالية قد تتعارض أحياناً مع إنقاذ جريح.","","all","safe","evidence_handling",["KO-FC-04-026","KO-RS-05-008","KO-RS-05-004"],["أول وصول","فصل الشهود"]),
("S19",5042,5057,"صفات المحقق: ملاحظة وذاكرة ونشاط وصبر ودقة وكتمان","يعرض الكتاب صفات يُنمّيها التمرين: قوة الملاحظة، الذاكرة، النشاط، الصبر، الدقة، وكتمان المعلومات. الأهم منهجياً أن الملاحظة مهارة تُدرَّب وتُسجَّل لا موهبة غامضة.","درّب نفسك على وصف مشهد بالكتابة ثم قارنه بصورة لتعرف ما فاتك.","الملاحظة تتأثر بالتوقع والتعب، وتقل دقة الذاكرة مع الوقت.","","all","safe","witness_reliability",["KO-RS-05-008","KO-RS-06-004"],["ملاحظة","توثيق"]),
("S19",5058,5083,"مصادر المعلومات متعددة ولكل منها قيمة وحدود","يذكر الكتاب الجمهور والمرشدين والمخبرين والخبراء والشرطة والصحافة. يلاحظ أن الصحافة تعين بنشر الصور والتحذير لكنها قد تضر بالتحقيق بنشر خطط أو معلومات حساسة. وتتطلب المصادر السرية حمايتها وتحقق صحة معلوماتها.","صنّف كل معلومة بمصدرها ودرجة ثقتك فيها قبل ربطها بغيرها.","مصدر مأجور أو ذو مصلحة قد يضخم أو يختلق.","كل ما نُشر في الصحف صحيح.","16-18","conceptual","witness_reliability",["KO-RS-05-001","KO-RS-05-004","KO-RS-06-020"],["مصدر","تحقق"]),
("S19",5084,5099,"علوم تعين الباحث: القانون وعلم النفس وعلم الإجرام","يرى الكتاب أن الباحث يحتاج إلى معرفة بالقانون الجنائي والإجراءات، وبعلم النفس، وبعلم الإجرام، دون أن يتقن كل العلوم بل يعرف متى يستعين بالخبير. فهم الإجراءات يحميه من إبطال أعماله.","اسأل في كل قضية: ما الذي يشترطه الإجراء كي يكون الدليل مقبولاً؟","الاستعانة بعلم النفس لا تعني قراءة النيات من الوجه أو السلوك.","","16-18","safe","reporting",["KO-RS-05-007","KO-RS-06-020"],["إجراءات","استعانة بخبير"]),
]
